// Rings as arrays of [lon, lat] in degrees (default: the land).
export function landRings(list = GLOBE_LAND) {
    return list.map((s) => {
        const n = s.split(',').map(Number);
        const ring = [];
        let x = 0;
        let y = 0;
        for (let k = 0; k < n.length; k += 2) {
            x += n[k];
            y += n[k + 1];
            ring.push([x / 2, y / 2]);
        }
        return ring;
    });
}
